// ─── Configuración ────────────────────────────────────────────────────────
// YouTube usa dos APIs distintas, ambas de autoservicio:
//   · Data API v3        → canal, vídeos y miniaturas
//   · YouTube Analytics  → vistas, retención y suscriptores del periodo
//
// La credencial de YouTube de n8n NO trae por defecto el permiso de analíticas.
// Activa "Custom Scopes" en la credencial y añade:
//   https://www.googleapis.com/auth/youtube.readonly
//   https://www.googleapis.com/auth/yt-analytics.readonly
//
// El canal se resuelve solo con mine=true: no hay que configurar ningún id.
const AJUSTES = {
  DATA_HOST: 'https://www.googleapis.com',
  ANALYTICS_HOST: 'https://youtubeanalytics.googleapis.com',
};

const env = (() => { try { return $env ?? {}; } catch { return {}; } })();
const DATA_HOST = env.YT_DATA_HOST || AJUSTES.DATA_HOST;
const ANALYTICS_HOST = env.YT_ANALYTICS_HOST || AJUSTES.ANALYTICS_HOST;


const COUNT = Math.min(Number($input.first().json.query?.count ?? 6), 50);

// La ventana de analíticas por vídeo cubre su vida útil reciente.
const iso = (d) => d.toISOString().slice(0, 10);
const endDate = iso(new Date(Date.now() - 86400000));
const startDate = iso(new Date(Date.now() - 366 * 86400000));

return [{ json: { dataHost: DATA_HOST, analyticsHost: ANALYTICS_HOST, count: COUNT, startDate, endDate } }];

// El canal no lista sus vídeos directamente: hay que pasar por la lista de
// reproducción de subidas que declara en contentDetails.
const cfg = $('Configuración').first().json;
const ch = $('Canal').first().json ?? {};

if (ch.error) throw new Error(ch.error.message);

const uploads = ch.items?.[0]?.contentDetails?.relatedPlaylists?.uploads;
if (!uploads) throw new Error('El canal no expone su lista de subidas');

return [{ json: { ...cfg, uploads } }];

// Se queda con los ids de los vídeos, que es lo que piden las dos llamadas
// siguientes.
const cfg = $('Recoger subidas').first().json;
const list = $('Lista de subidas').first().json ?? {};

if (list.error) throw new Error(list.error.message);

const ids = (list.items ?? [])
  .map((i) => i.contentDetails?.videoId)
  .filter(Boolean);

return [{ json: { ...cfg, ids, idList: ids.join(',') } }];

// Une los vídeos con sus estadísticas públicas y su retención real.
const videos = $('Vídeos').first().json ?? {};
const an = $('Retención por vídeo').first().json ?? {};

if (videos.error) return [{ json: { source: 'youtube', error: videos.error.message, posts: [] } }];

// Analytics con dimensions=video devuelve una fila por vídeo.
const cols = (an.columnHeaders ?? []).map((c) => c.name);
const iVideo = cols.indexOf('video');
const byVideo = {};
for (const row of an.rows ?? []) {
  if (iVideo === -1) continue;
  const entry = {};
  cols.forEach((c, i) => { entry[c] = row[i]; });
  byVideo[row[iVideo]] = entry;
}

const fmt = (n) => (n == null ? null
  : n >= 1e6 ? (n / 1e6).toFixed(1) + 'M'
  : n >= 1e3 ? (n / 1e3).toFixed(1) + 'K'
  : String(n));

// ISO 8601 (PT1H2M3S) a mm:ss o h:mm:ss.
function duration(iso) {
  const m = /^P(?:(\d+)D)?T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?$/.exec(iso ?? '');
  if (!m) return null;
  const [, d, h, mi, s] = m.map((x) => (x == null ? 0 : Number(x)));
  const total = d * 86400 + h * 3600 + mi * 60 + s;
  const pad = (n) => String(n).padStart(2, '0');
  return total >= 3600
    ? `${Math.floor(total / 3600)}:${pad(Math.floor((total % 3600) / 60))}:${pad(total % 60)}`
    : `${Math.floor(total / 60)}:${pad(total % 60)}`;
}

const posts = (videos.items ?? []).map((v) => {
  const st = v.statistics ?? {};
  const th = v.snippet?.thumbnails ?? {};
  const a = byVideo[v.id] ?? {};
  const retention = a.averageViewPercentage;

  return {
    id: v.id,
    title: (v.snippet?.title ?? 'Sin título').slice(0, 90),
    excerpt: (v.snippet?.description ?? '').slice(0, 220),
    // Un Short dura como mucho tres minutos.
    kind: (v.contentDetails?.duration ?? '').match(/^PT([1-9]\d?|1[0-7]\d)S$/) ? 'short' : 'video',
    image: (th.maxres ?? th.high ?? th.medium ?? th.default)?.url ?? null,
    duration: duration(v.contentDetails?.duration),
    permalink: `https://www.youtube.com/watch?v=${v.id}`,
    publishedAt: v.snippet?.publishedAt ?? null,
    metrics: [
      { label: 'Vistas', value: fmt(Number(st.viewCount)) },
      { label: 'Me gusta', value: fmt(Number(st.likeCount)) },
      { label: 'Retención', value: retention == null ? null : Number(retention).toFixed(0) + '%' },
    ],
  };
});

return [{ json: { source: 'youtube', errors: [an.error?.message].filter(Boolean), posts } }];
